def average(numbers):
    """Return the arithmetic mean of a list of numbers.

    None values are ignored (missing readings, not zeros). An empty list
    or a list of only None values returns 0. The result is rounded to
    2 decimal places.
    """
    valid = [n for n in numbers if n is not None]
    if not valid:
        return 0
    return round(sum(valid) / len(valid), 2)
